      programB: "Programma B",
      manualIrrigation: "Irrigazione Manuale",
      line: "Linea",
      program: "Programma",
      inactive: "Non attivo",
      active: "Attivo",
      startAt: "Avvio",
      duration: "Durata",
      totalDuration: "Durata totale",
      irrigationDays: "Giorni di irrigazione",
      irrigationStart: "Inizio irrigazione",
